import Items from "../ui/items";
import Container from "../components/container";
import ProfileCard from "../ui/profile-card";
import SectionHeading from "../ui/section-heading";
import { frameworksAndTools,clouds,marketingAndAds } from "../lib/skills-data";
import SkillCard from "../components/cards/skill-card";

const About = async ({ isPage = false }: { isPage?: boolean }) => {

  return (
    <Container
      id="about"
      className="w-full p-5"
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      transition={{ duration: 0.5 }}
    >
      <Items
        Number="02"
        title="About Me"
        headingTag={isPage ? "h1" : "h2"}
        des="Full-stack developer specializing in high-performance web applications built with clean, scalable code to drive user growth and digital transformation."
      />
      <ProfileCard />
      <SectionHeading className="mt-12">
        Tech Stack.
      </SectionHeading>
      <div className="grid grid-cols-2 gap-px bg-border md:grid-cols-4">
        {[...clouds, ...frameworksAndTools].map((skill) => (
          <SkillCard key={skill.label} skill={skill} />
        ))}
      </div>

    </Container>
  );
};

export default About;

import { cn } from "../../lib/utils";

type Skill = {
  icon: React.ReactNode;
  label: string;
};

type SkillCardProps = {
  skill: Skill;
  className?: string;
};

export default function LanguageCard({
  skill,
  className,
}: Readonly<SkillCardProps>) {
  return (
    <div
      className={cn(
        "gap-4 p-4  border transition-colors duration-300 flex items-center justify-center bg-background px-4 py-8 md:p-8 hover:bg-white/8  group select-none cursor-pointer",
        className,
      )}
    >
      <div className="shrink-0 transition-transform duration-500 group-hover:scale-110">
        {skill.icon}
      </div>
      <div className="flex-1 min-w-0">
        <p className="text-lg sm:text-xl font-bold text-white tracking-tight group-hover:text-blue-400 transition-colors truncate">
          {skill.label}
        </p>
      </div>
    </div>
  );
}

import * as motion from "motion/react-client";
import { type Skill } from "../../lib/skills-data";
import { cn } from "../../lib/utils";

interface SkillCardProps {
  skill: Skill;
  className?: string;
}

const SkillCard = ({ skill, className }: SkillCardProps) => {
  return (
    <motion.div
      className={cn(
        "gap-4 p-2  border transition-colors duration-300 flex items-center justify-center bg-background px-2 py-4 md:p-8 hover:bg-white/8  group select-none cursor-pointer",
        className,
      )}
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.2 }}
    >
      <div className="transition-transform duration-500 group-hover:scale-110 shrink-0">
        {skill.icon}
      </div>
      <div className="flex-1 min-w-0">
      <p className="text-xl font-bold text-white tracking-tight group-hover:text-blue-400 transition-colors">
        {skill.label}
      </p>
      </div>
    </motion.div>
  );
};

export default SkillCard;

